%[text] # Introduction to Vectors
V = [1 2 3] %[output:5acc0e4c]
V(2)  %[output:440408b2]
transposeV = V' %[output:6d56842f]
%%
NewV = V + 4 %[output:3b533e90]
V(4) = 7 %[output:95f91195]
V(8) = 10 %[output:9767968e]
V = [V 11] %[output:4d930b13]
%%
V1 = randi(9,[5 1]) %[output:429ae715]
V2 = randi(9,[1 5]) %[output:60c414a8]
W = V1 + V2 %[output:332ded01]
%%
U = [1 2 3] %[output:1d7673e4]
U = U.^2 %[output:9819d7dc]
%%
tic
for ii = 1:100
A = [1 2 3];
B = [3 2 5];
product = 0;
for k = 1:3
    product = product + A(k)*B(k);
end
end
toc %[output:6156fe5d]
%%
tic
for ii = 1:100
product = dot(A,B);
end
toc %[output:82f726d5]
%%
sum(A.*B) %[output:44615161]
%%
plot(A,B) %[output:42906dae]
hold on %[output:42906dae]
scatter(A,B,"filled") %[output:42906dae]
hold off %[output:42906dae]

grid on %[output:42906dae]
legend("Position", [0.7071 0.2211 0.1458, 0.0963]) %[output:42906dae]
title("Some plot") %[output:42906dae]
xlabel("x axis") %[output:42906dae]
ylabel("y axis") %[output:42906dae]
%%
figure; %[output:0b184565]
plot(A, B, 'LineWidth', 2, 'Color', 'b'); %[output:0b184565]
hold on; %[output:0b184565]
scatter(A, B, 100, 'filled', 'MarkerFaceColor', 'r'); %[output:0b184565]
hold off; %[output:0b184565]

grid on; %[output:0b184565]
legend("Data Points", 'Location', 'best'); %[output:0b184565]
title("Plot of Vector A vs Vector B"); %[output:0b184565]
xlabel("Vector A"); %[output:0b184565]
ylabel("Vector B"); %[output:0b184565]

